<?php require_once __DIR__.'/../model/dashboard_model.php';require_once __DIR__.'/../model/doctor_model.php';require_once __DIR__.'/../model/appointment_model.php';$u=$_SESSION['user'];$dm=new DashboardModel();$docm=new DoctorModel();$am=new AppointmentModel();$stats=[];$recent=[];if($u['role']==='admin')foreach(['Users','Doctors','Departments','Appointments'] as $x)$stats[$x]=$dm->count(strtolower($x));elseif($u['role']==='patient'){$stats=$dm->patient($u['id']);$recent=array_slice($am->patient($u['id']),0,5);}elseif($u['role']==='doctor'){$d=$docm->byUser($u['id']);$stats=$d?$dm->doctor($d['id']):[];}else $recent=$am->all(date('Y-m-d'));require __DIR__.'/../views/dashboard.php';?>